  ('Lumière', 0, 'Évocation', '{"Barde","Clerc","Ensorceleur","Magicien"}', '1 action', 'Contact', 'V, M', '1 heure', false, false, 'Un objet émet une lumière vive sur 6 m et faible sur 6 m de plus.'),
